  /// Submit a shelter intake form that mixes files, scalars, and structured values
  ///
  /// * Path: `POST /intake/{formId}`
  pub async fn submit_intake_form(
    &self,
    request: SubmitIntakeFormRequest,
  ) -> anyhow::Result<ApiResponse<IntakeForm, ()>> {
    request.validate().context("parameter validation")?;
    let mut url = self.base_url.clone();
    url
      .path_segments_mut()
      .map_err(|()| anyhow::anyhow!("URL cannot be a base"))?
      .push("intake")
      .push(&request.path.form_id.clone());
    let mut req_builder = self.client.post(url);
    if let Some(api_key) = &self.api_key_auth {
      req_builder = req_builder.header(X_API_KEY, secrecy::ExposeSecret::expose_secret(api_key));
    }
    let body = request.body;
    let mut form = reqwest::multipart::Form::new().percent_encode_noop();
    form = form.text("name", body.name);
    if let Some(value) = body.file_name {
      form = form.text("fileName", value);
    }
    if let Some(value) = body.r#type {
      form = form.text("type", value);
    }
    if let Some(value) = body.resume {
      form = form.text("résumé", value);
    }
    if let Some(value) = body.file {
      form = form.part(
        "file",
        reqwest::multipart::Part::bytes(value)
          .file_name("file")
          .mime_str("application/octet-stream")?,
      );
    }
    for value in body.attachments {
      form = form.part(
        "attachments",
        reqwest::multipart::Part::bytes(value)
          .file_name("attachments")
          .mime_str("application/octet-stream")?,
      );
    }
    form = form.part(
      "thumbnail",
      reqwest::multipart::Part::bytes(body.thumbnail)
        .file_name("thumbnail")
        .mime_str("application/octet-stream")?,
    );
    if let serde_json::Value::String(text) = serde_json::to_value(serde_with::ser::SerializeAsWrap::<
      _,
      serde_with::base64::Base64,
    >::new(&body.encoded))?
    {
      form = form.text("encoded", text);
    }
    form = form.text("count", body.count.to_string());
    if let Some(value) = body.ratio {
      form = form.text("ratio", value.to_string());
    }
    if let Some(value) = body.enabled {
      form = form.text("enabled", value.to_string());
    }
    if let Some(value) = body.quality {
      form = form.text("quality", value.to_string());
    }
    if let Some(value) = body.level {
      form = form.text("level", value.to_string());
    }
    for value in body.tags.into_iter().flatten() {
      form = form.text("tags", value);
    }
    if let Some(value) = body.created_at
      && let serde_json::Value::String(text) = serde_json::to_value(value)?
    {
      form = form.text("createdAt", text);
    }
    if let Some(value) = body.address {
      form = form.part(
        "address",
        reqwest::multipart::Part::text(serde_json::to_string(&value)?).mime_str("application/json")?,
      );
    }
    for value in body.addresses.into_iter().flatten() {
      form = form.part(
        "addresses",
        reqwest::multipart::Part::text(serde_json::to_string(&value)?)
          .mime_str("application/vnd.petstore.address+json")?,
      );
    }
    if let Some(value) = body.note {
      form = form.part("note", reqwest::multipart::Part::text(value).mime_str("text/markdown")?);
    }
    if let Some(value) = body.labels {
      match serde_json::to_value(value)? {
        serde_json::Value::Null => {}
        serde_json::Value::String(text) => {
          form = form.text("labels", text);
        }
        other => {
          form = form.part(
            "labels",
            reqwest::multipart::Part::text(other.to_string()).mime_str("application/json")?,
          );
        }
      }
    }
    let mut items = vec![];
    for value in body.ids.into_iter().flatten() {
      items.push(value.to_string());
    }
    if !items.is_empty() {
      form = form.text("ids", items.join("|"));
    }
    for value in body.colors.into_iter().flatten() {
      form = form.text("colors", value);
    }
    if let Some(value) = body.filter
      && let serde_json::Value::Object(members) = serde_json::to_value(value)?
    {
      for (key, member) in members {
        let text = match member {
          serde_json::Value::Null => continue,
          serde_json::Value::String(text) => text,
          other => other.to_string(),
        };
        form = form.text(format!("filter[{key}]"), text);
      }
    }
    if let Some(value) = body.range
      && let serde_json::Value::Object(members) = serde_json::to_value(value)?
    {
      let mut items = vec![];
      for (key, member) in members {
        let text = match member {
          serde_json::Value::Null => continue,
          serde_json::Value::String(text) => text,
          other => other.to_string(),
        };
        items.push(key);
        items.push(text);
      }
      if !items.is_empty() {
        form = form.text("range", items.join(","));
      }
    }
    if let Some(value) = body.extras
      && let serde_json::Value::Object(members) = serde_json::to_value(value)?
    {
      for (key, member) in members {
        let text = match member {
          serde_json::Value::Null => continue,
          serde_json::Value::String(text) => text,
          other => other.to_string(),
        };
        form = form.text(key, text);
      }
    }
    if let Some(value) = body.options
      && let serde_json::Value::Object(members) = serde_json::to_value(value)?
    {
      for (key, member) in members {
        let text = match member {
          serde_json::Value::Null => continue,
          serde_json::Value::String(text) => text,
          other => other.to_string(),
        };
        form = form.text(format!("options[{key}]"), text);
      }
    }
    req_builder = req_builder.multipart(form);
    let response = req_builder.send().await?;
    SubmitIntakeFormRequest::parse_response(response).await
  }
  /// Upload any number of files under one part name
  ///
  /// * Path: `POST /media`
  pub async fn upload_media(&self, request: UploadMediaRequest) -> anyhow::Result<ApiResponse<MediaReceipt, ()>> {
    request.validate().context("parameter validation")?;
    let mut url = self.base_url.clone();
    url
      .path_segments_mut()
      .map_err(|()| anyhow::anyhow!("URL cannot be a base"))?
      .push("media");
    let mut req_builder = self.client.post(url);
    if let Some(api_key) = &self.api_key_auth {
      req_builder = req_builder.header(X_API_KEY, secrecy::ExposeSecret::expose_secret(api_key));
    }
    if let Some(body) = request.body {
      let has_parts =
        body.file.as_ref().is_some_and(|items| !items.is_empty()) || body.cover.is_some() || body.note.is_some();
      let mut form = reqwest::multipart::Form::new().percent_encode_noop();
      for value in body.file.into_iter().flatten() {
        form = form.part(
          "file",
          reqwest::multipart::Part::bytes(value)
            .file_name("file")
            .mime_str("application/octet-stream")?,
        );
      }
      if let Some(value) = body.cover {
        form = form.part(
          "cover",
          reqwest::multipart::Part::bytes(value)
            .file_name("cover")
            .mime_str("image/png")?,
        );
      }
      if let Some(value) = body.note {
        form = form.text("note", value);
      }
      req_builder = if has_parts {
        req_builder.multipart(form)
      } else {
        req_builder
          .header(
            http::header::CONTENT_TYPE,
            format!("multipart/form-data; boundary={}", form.boundary()),
          )
          .body(format!("--{}--\r\n", form.boundary()))
      };
    }
    let response = req_builder.send().await?;
    UploadMediaRequest::parse_response(response).await
  }
